1	import { ok, fail } from './result.js';
2	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	import { roundCents } from './money.js';
6	import { isValidDate } from './dates.js';
7	
8	function isValidDiscount(discountPercent) {
9	  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
10	}
11	
12	/**
13	 * Calculate the total for a single line (qty * unitPrice).
14	 * @param {{ qty: number, unitPrice: number }}
15	 * @returns {number}
16	 */
17	export function lineTotal(line) {
18	  return line.qty * line.unitPrice;
19	}
20	
21	/**
22	 * Calculate the discount for a single line.
23	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
24	 * @returns {number}
25	 */
26	function lineDiscount(line) {
27	  const discount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
28	  return Math.max(0, roundCents(discount));
29	}
30	
31	/**
32	 * Calculate the VAT for a single line.
33	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
34	 * @returns {number}
35	 */
36	function lineVat(line) {
37	  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
38	  const vat = amountAfterDiscount * (line.vatRate ?? 0) / 100;
39	  return Math.max(0, roundCents(vat));
40	}
41	
42	/**
43	 * Calculate subtotal, discount, VAT, and total for an invoice.
44	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
45	 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
46	 */
47	export function invoiceTotals(invoice) {
48	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
49	  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
50	  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
51	  const total = Math.max(0, subtotal - discount + vat);
52	  return { subtotal, discount, vat, total };
53	}
54	
55	/**
56	 * Create a draft invoice.
57	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
58	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
59	 */
60	export function createInvoice({ customerId, issueDate, lines }) {
61	  const normalizedCustomerId = normalizeId(customerId);
62	  const customer = getCustomer(normalizedCustomerId);
63	  if (!customer.ok) return customer;
64	
65	  if (!isValidDate(issueDate)) {
66	    return fail('DATE_INVALID');
67	  }
68	
69	  if (!Array.isArray(lines) || lines.length === 0) {
70	    return fail('NO_LINES');
71	  }
72	
73	  const invoiceLines = [];
74	  for (const line of lines) {
75	    if (!Number.isInteger(line.qty) || line.qty <= 0) {
76	      return fail('QTY_INVALID');
77	    }
78	
79	    const discountPercent = 'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customer.value.tier];
80	    if (!isValidDiscount(discountPercent)) {
81	      return fail('DISCOUNT_INVALID');
82	    }
83	
84	    const product = getProduct(line.sku);
85	    if (!product.ok) return product;
86	
87	    invoiceLines.push({
88	      sku: line.sku,
89	      name: product.value.name,
90	      qty: line.qty,
91	      unitPrice: product.value.unitPrice,
92	      vatRate: product.value.vatRate,
93	      discountPercent,
94	    });
95	  }
96	
97	  return ok({
98	    customerId: normalizedCustomerId,
99	    issueDate,
100	    status: 'draft',
101	    lines: invoiceLines,
102	  });
103	}
104	
105	/**
106	 * Add a line to an invoice or increase its quantity if it already exists.
107	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
108	 * @param {{ sku: string, qty: number, discountPercent?: number }} param
109	 */
110	export function addLine(invoice, param) {
111	  if (invoice.status !== 'draft') {
112	    return fail('NOT_DRAFT');
113	  }
114	
115	  if (!Number.isInteger(param.qty) || param.qty <= 0) {
116	    return fail('QTY_INVALID');
117	  }
118	
119	  const customer = getCustomer(invoice.customerId);
120	  if (!customer.ok) return customer;
121	
122	  const discount = 'discountPercent' in param ? param.discountPercent : TIER_DISCOUNTS[customer.value.tier];
123	  if (!isValidDiscount(discount)) {
124	    return fail('DISCOUNT_INVALID');
125	  }
126	
127	  const product = getProduct(param.sku);
128	  if (!product.ok) return product;
129	
130	  const newLines = invoice.lines.map((line) => ({ ...line }));
131	  const existingLineIndex = newLines.findIndex((line) => line.sku === param.sku);
132	
133	  if (existingLineIndex >= 0) {
134	    newLines[existingLineIndex].qty += param.qty;
135	  } else {
136	    newLines.push({
137	      sku: param.sku,
138	      name: product.value.name,
139	      qty: param.qty,
140	      unitPrice: product.value.unitPrice,
141	      vatRate: product.value.vatRate,
142	      discountPercent: discount,
143	    });
144	  }
145	
146	  return ok({
147	    customerId: invoice.customerId,
148	    issueDate: invoice.issueDate,
149	    status: invoice.status,
150	    lines: newLines,
151	  });
152	}
153	
154	/**
155	 * Remove a line from an invoice.
156	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
157	 * @param {string} sku
158	 */
159	export function removeLine(invoice, sku) {
160	  if (invoice.status !== 'draft') {
161	    return fail('NOT_DRAFT');
162	  }
163	
164	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
165	  if (lineIndex < 0) {
166	    return fail('LINE_NOT_FOUND');
167	  }
168	
169	  if (invoice.lines.length === 1) {
170	    return fail('NO_LINES');
171	  }
172	
173	  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
174	
175	  return ok({
176	    customerId: invoice.customerId,
177	    issueDate: invoice.issueDate,
178	    status: invoice.status,
179	    lines: newLines,
180	  });
181	}
182	
183	/**
184	 * Issue an invoice (change status from draft to issued and assign a number).
185	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
186	 * @param {Array<string>} existingNumbers - Invoice numbers already used
187	 */
188	export function issueInvoice(invoice, existingNumbers) {
189	  if (invoice.status !== 'draft') {
190	    return fail('NOT_DRAFT');
191	  }
192	
193	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
194	
195	  return ok({
196	    number,
197	    customerId: invoice.customerId,
198	    issueDate: invoice.issueDate,
199	    status: 'issued',
200	    lines: invoice.lines.map((line) => ({ ...line })),
201	  });
202	}
