import test from 'node:test';
import assert from 'node:assert/strict';
import { isValidDate, addDays, daysBetween } from '../src/dates.js';

test('isValidDate accepts valid dates', () => {
  assert.equal(isValidDate('2026-10-07'), true);
  assert.equal(isValidDate('2025-01-01'), true);
  assert.equal(isValidDate('2026-12-31'), true);
});

test('isValidDate rejects invalid formats', () => {
  assert.equal(isValidDate('10/07/2026'), false);
  assert.equal(isValidDate('2026/10/07'), false);
  assert.equal(isValidDate('07-10-2026'), false);
  assert.equal(isValidDate('2026-10-7'), false);
});

test('isValidDate rejects invalid dates', () => {
  assert.equal(isValidDate('2026-02-30'), false);
  assert.equal(isValidDate('2026-04-31'), false);
  assert.equal(isValidDate('2025-13-01'), false);
  assert.equal(isValidDate('2026-00-01'), false);
});

test('isValidDate accepts leap year dates', () => {
  assert.equal(isValidDate('2024-02-29'), true);
  assert.equal(isValidDate('2025-02-28'), true);
});

test('isValidDate rejects invalid leap year dates', () => {
  assert.equal(isValidDate('2025-02-29'), false);
});

test('isValidDate rejects empty strings', () => {
  assert.equal(isValidDate(''), false);
});

test('isValidDate rejects null and undefined', () => {
  assert.equal(isValidDate(null), false);
  assert.equal(isValidDate(undefined), false);
});

test('addDays adds positive days', () => {
  assert.equal(addDays('2026-10-07', 1), '2026-10-08');
  assert.equal(addDays('2026-10-07', 5), '2026-10-12');
  assert.equal(addDays('2026-10-07', 10), '2026-10-17');
});

test('addDays subtracts negative days', () => {
  assert.equal(addDays('2026-10-07', -1), '2026-10-06');
  assert.equal(addDays('2026-10-07', -5), '2026-10-02');
});

test('addDays handles month boundaries', () => {
  assert.equal(addDays('2026-10-31', 1), '2026-11-01');
  assert.equal(addDays('2026-11-01', -1), '2026-10-31');
});

test('addDays handles year boundaries', () => {
  assert.equal(addDays('2026-12-31', 1), '2027-01-01');
  assert.equal(addDays('2027-01-01', -1), '2026-12-31');
});

test('addDays handles zero days', () => {
  assert.equal(addDays('2026-10-07', 0), '2026-10-07');
});

test('addDays handles large day increments', () => {
  assert.equal(addDays('2026-10-07', 365), '2027-10-07');
});

test('addDays handles leap year transitions', () => {
  assert.equal(addDays('2024-02-28', 1), '2024-02-29');
  assert.equal(addDays('2024-02-29', 1), '2024-03-01');
});

test('daysBetween calculates positive difference', () => {
  assert.equal(daysBetween('2026-10-07', '2026-10-08'), 1);
  assert.equal(daysBetween('2026-10-07', '2026-10-12'), 5);
  assert.equal(daysBetween('2026-10-07', '2026-10-17'), 10);
});

test('daysBetween calculates negative difference', () => {
  assert.equal(daysBetween('2026-10-07', '2026-10-06'), -1);
  assert.equal(daysBetween('2026-10-07', '2026-10-02'), -5);
});

test('daysBetween with same dates returns zero', () => {
  assert.equal(daysBetween('2026-10-07', '2026-10-07'), 0);
});

test('daysBetween across month boundaries', () => {
  assert.equal(daysBetween('2026-10-31', '2026-11-01'), 1);
  assert.equal(daysBetween('2026-11-01', '2026-10-31'), -1);
});

test('daysBetween across year boundaries', () => {
  assert.equal(daysBetween('2026-12-31', '2027-01-01'), 1);
  assert.equal(daysBetween('2027-01-01', '2026-12-31'), -1);
});

test('daysBetween across full years', () => {
  assert.equal(daysBetween('2025-01-01', '2026-01-01'), 365);
  assert.equal(daysBetween('2024-01-01', '2025-01-01'), 366); // leap year
});

test('daysBetween works in UTC and handles day-long periods consistently', () => {
  const a = '2026-10-07';
  const b = '2026-10-10';
  const days = daysBetween(a, b);
  assert.equal(days, 3);
  assert.equal(daysBetween(b, a), -3);
  assert.equal(addDays(a, days), b);
});

test('addDays and daysBetween are inverse operations', () => {
  const start = '2026-06-15';
  const offset = 123;
  const end = addDays(start, offset);
  assert.equal(daysBetween(start, end), offset);
});

test('daysBetween with irregular date intervals', () => {
  assert.equal(daysBetween('2026-02-28', '2026-03-01'), 1);
  assert.equal(daysBetween('2024-02-28', '2024-03-01'), 2); // leap year
});

